import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt(), found = 0;
        // has[i]: the direct edge i -- i+1 exists
        boolean[] has = new boolean[n + 1];
        for (int e = 0; e < m; e++) {
            int a = nextInt(), b = nextInt();
            if (Math.abs(a - b) == 1 && !has[Math.min(a, b)]) {
                has[Math.min(a, b)] = true;
                found++;
            }
        }
        System.out.println(found == n - 1 ? 1 : 0);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, m := next(), next()
	// has[i]: the direct edge i -- i+1 exists
	has := make([]bool, n+1)
	found := 0
	for e := 0; e < m; e++ {
		a, b := next(), next()
		if a-b == 1 || b-a == 1 {
			if !has[min(a, b)] {
				has[min(a, b)] = true
				found++
			}
		}
	}
	if found == n-1 {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}
